const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sichuan Basin geometry
  const sichuanBasin = ee.Geometry.Rectangle([103, 28, 108, 32]);

  // 2. Load MODIS AOD data for 2006
  const aod2006 = ee.ImageCollection('MODIS/061/MOD08_M3')
    .filterDate('2006-01-01', '2006-12-31')
    .filterBounds(sichuanBasin)
    .select('AOD_550_Dark_Target_Deep_Blue_Combined_Mean');

  const size2006 = aod2006.size().getInfo();
  console.log(`2006 Images: ${size2006}`);

  if (size2006 === 0) {
    console.log('No data for 2006');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Load MODIS AOD data for 2020
  const aod2020 = ee.ImageCollection('MODIS/061/MOD08_M3')
    .filterDate('2020-01-01', '2020-12-31')
    .filterBounds(sichuanBasin)
    .select('AOD_550_Dark_Target_Deep_Blue_Combined_Mean');

  const size2020 = aod2020.size().getInfo();
  console.log(`2020 Images: ${size2020}`);

  if (size2020 === 0) {
    console.log('No data for 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate mean AOD for each year with scaling factor
  const meanAOD2006 = aod2006.mean().multiply(0.001);
  const meanAOD2020 = aod2020.mean().multiply(0.001);

  // 5. Get statistics
  const stats2006 = meanAOD2006.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = meanAOD2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sichuanBasin,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const val2006 = stats2006['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_mean'];
  const count2006 = stats2006['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_count'];
  const val2020 = stats2020['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_mean'];
  const count2020 = stats2020['AOD_550_Dark_Target_Deep_Blue_Combined_Mean_count'];

  console.log(`2006 AOD: ${val2006?.toFixed(3)}, Pixels: ${count2006}`);
  console.log(`2020 AOD: ${val2020?.toFixed(3)}, Pixels: ${count2020}`);

  // 6. Validation and answer
  if (count2006 === 0 || count2020 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (val2006 === null || val2020 === null || isNaN(val2006) || isNaN(val2020)) {
    console.log('Calculation failed - invalid results');
    console.log('<answer>C3</answer>');
    return;
  }

  if (val2006 < 0 || val2006 > 5 || val2020 < 0 || val2020 > 5) {
    console.log('Invalid AOD range detected');
    console.log('<answer>C3</answer>');
    return;
  }

  const decrease = val2020 < val2006;
  const change = ((val2020 - val2006) / val2006 * 100).toFixed(1);
  console.log(`Change: ${change}% (${decrease ? 'decreased' : 'increased/stable'})`);

  if (decrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
